/////////////////////////////////////////////////////////////////////////////////////////////////////////
//					Implementation of printf like feature using ARM Cortex M3/M4/ ITM functionality
//					This function will not work for ARM Cortex M0/M0+
/////////////////////////////////////////////////////////////////////////////////////////////////////////

//Debug Exception and Monitor Control Register base address
/** @brief Debug Exception and Monitor Control Register — bit 24 (TRCENA) gates all trace, including the ITM. */
#define DEMCR *((volatile uint32_t *)0xE000EDFCU)

/* ITM register addresses */
/** @brief ITM stimulus port 0: writing a byte here emits it on the SWO pin. Bit 0 reads back as "FIFO ready". */
#define ITM_STIMULUS_PORT0 *((volatile uint32_t *)0xE0000000)
/** @brief ITM Trace Enable: one bit per stimulus port; port 0 must be enabled before a write is accepted. */
#define ITM_TRACE_EN *((volatile uint32_t *)0xE0000E00)

/**
 * @brief Emit one character on the ITM stimulus port (the SWO trace pin).
 * @param ch The character to send.
 * @note Busy-waits for the ITM FIFO to drain, so with no debugger attached and
 *       the trace port unclocked this can spin. It is a debug path only — the
 *       ADAS tasks never call `printf`.
 */
void ITM_SendChar(uint8_t ch)
{
  //Enable TRCENA
  DEMCR |= (1 << 24);

  //enable stimulus port 0
  ITM_TRACE_EN |= (1 << 0);

  // read FIFO status in bit [0]:
  while (!(ITM_STIMULUS_PORT0 & 1))
    ;

  //Write to ITM stimulus port0
  ITM_STIMULUS_PORT0 = ch;
}

/* Variables */

/**
 * @brief Character sink for `printf`, overridable by the application.
 * @param ch The character to emit.
 * @return The character written.
 * @note Weak, and not overridden here: @ref _write goes straight to the ITM.
 */
extern int __io_putchar(int ch) __attribute__((weak));

/**
 * @brief Character source for `scanf`, overridable by the application.
 * @return The character read.
 */
extern int __io_getchar(void) __attribute__((weak));

/** @brief Backing store for @ref environ — an empty environment. */
char *__env[1] = { 0 };

/** @brief The process environment Newlib hands to `getenv`; always empty here. */
char **environ = __env;

