/**
 * @brief Process ID of the "current process".
 * @return Always 1 — there is only ever one program on the MCU.
 */
int _getpid(void)
{
  return 1;
}

/**
 * @brief Send a signal to a process. There are no processes, so this always fails.
 * @param pid Ignored.
 * @param sig Ignored.
 * @return -1, with `errno` set to `EINVAL`.
 */
int _kill(int pid, int sig)
{
  (void)pid;
  (void)sig;
  errno = EINVAL;
  return -1;
}

/**
 * @brief Terminate the program.
 * @param status Exit status; passed to @ref _kill and otherwise ignored.
 * @note Does not return — there is nowhere to exit *to*, so it hangs in a loop.
 *       In practice the watchdog then resets the MCU.
 */
void _exit(int status)
{
  _kill(status, -1);
  while (1)
  {
  } /* Make sure we hang here */
}

/**
 * @brief Backend for `scanf` and friends: read @p len characters via `__io_getchar`.
 * @param file Ignored — there is no file system.
 * @param[out] ptr Buffer to fill.
 * @param len Number of characters to read.
 * @return @p len, always: the read is assumed to succeed.
 */
__attribute__((weak)) int _read(int file, char *ptr, int len)
{
  (void)file;
  int DataIdx;

  for (DataIdx = 0; DataIdx < len; DataIdx++)
  {
    *ptr++ = __io_getchar();
  }

  return len;
}

/**
 * @brief Backend for `printf`: push @p len characters out over the ITM.
 * @param file Ignored — stdout and stderr both land here.
 * @param[in] ptr Characters to write.
 * @param len How many to write.
 * @return @p len, always.
 */
__attribute__((weak)) int _write(int file, char *ptr, int len)
{
  (void)file;
  int DataIdx;

  for (DataIdx = 0; DataIdx < len; DataIdx++)
  {
    ITM_SendChar(*ptr++);
  }
  return len;
}

